INSERT INTO nhs_seed_guard VALUES ('exclusive seed lock', COALESCE(GET_LOCK('carlos.nhs_synthetic_dev_seed', 10), 0));
INSERT INTO nhs_seed_guard SELECT 'development database and provider context', IF(DATABASE() = 'oscar' AND EXISTS (SELECT 1 FROM security WHERE user_name='carlosdoc' AND provider_no='999998') AND EXISTS (SELECT 1 FROM program_provider WHERE provider_no='999998' AND program_id=10034 AND role_id=2) AND EXISTS (SELECT 1 FROM program WHERE id=10034 AND name='OSCAR') AND (SELECT COUNT(*) FROM information_schema.tables WHERE table_schema=DATABASE() AND table_name IN ('demographic','casemgmt_note') AND engine='InnoDB')=2, 1, 0);
INSERT INTO nhs_seed_guard SELECT 'chart marker collision', IF((SELECT COUNT(*) FROM demographic WHERE chart_no=CONVERT(0x4e485353594e303031 USING utf8mb4)) <= 1 AND NOT EXISTS (SELECT 1 FROM demographic WHERE chart_no=CONVERT(0x4e485353594e303031 USING utf8mb4) AND NOT (alias <=> CONVERT(0x4e48532073796e7468657469632032383537303131392d396364632d343132302d393863302d346564623736636633366133 USING utf8mb4))), 1, 0);
